interface.definition:
a!localVariables(
  local!solicitudes: rule!DEMO_QR_GetSolicitudes(estado: ri!estadoFiltro),
  a!gridField(
    label: "Solicitudes",
    data: local!solicitudes,
    columns: {
      a!gridColumn(label: "Solicitante", value: fv!row.solicitante),
      a!gridColumn(label: "Importe", value: fv!row.importe),
      a!gridColumn(label: "Estado", value: fv!row.estado)
    },
    pageSize: 20
  )
)
